426	function renderReport(data, status) {
427	  if (status === 400) {
428	    showReport('<div class="banner bad">整份文件已拒绝导入，本次没有新增客户，原有客户资料保持原样。<br>原因：' +
429	      esc(data.error || "未知错误") + '</div>');
430	    return;
431	  }
432	  const failures = data.failures || [];
433	  let out = '<div class="banner ok">新增 <b>' + esc(data.imported_count) + '</b> 条，' +
434	    '未导入 <b>' + failures.length + '</b> 条。</div>';
435	  if (failures.length) {
436	    out += '<div class="failures"><p><b>未导入记录（编号按原文件数据记录，表头不计入）：</b></p><ul>';
437	    out += failures.map(f =>
438	      "<li>第 <b>" + esc(f.row) + "</b> 条：" + esc(f.reason) + "</li>").join("");
439	    out += "</ul></div>";
440	  }
441	  showReport(out);
442	}
443	
444	// 首次读取失败时页内已显示读取失败提示且表格保持空白/原状，这里吞掉拒绝即可，
445	// 不使用弹窗、不清空任何已有内容。
446	loadClients().catch(() => {});
447	</script>
448	</body>
449	</html>
450	'''
451	
452	
453	class FileError(Exception):
454	    """文件级错误：整份文件拒绝导入（HTTP 400）。"""
455	
456	
457	class BatchUpdateError(Exception):
458	    """批量修改请求级错误：整次修改拒绝（HTTP 400）。"""
459	
460	
461	FIELD_LABELS = {
462	    "source": "来源",
463	    "region": "地区",
464	    "industry": "行业",
465	    "important_date": "重要日期",
466	}
467	
