const chrome = spawn('google-chrome',['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--remote-debugging-port=0',`--user-data-dir=${profile}`],{stdio:['ignore','pipe','pipe']});
let wsLine=null;
chrome.stderr.on('data',async d=>{
  const m=String(d).match(/DevTools listening on (ws:\/\/\S+)/);
  if(!m||wsLine) return; wsLine=m[1];
  const httpBase=wsLine.replace(/^ws/,'http').replace(/\/devtools\/.*$/,'');
